const state={token:localStorage.getItem('sm_token')||'',user:null,page:'dashboard',navVersion:0};
function refreshIcons(root=document){if(window.lucide&&typeof window.lucide.createIcons==='function')window.lucide.createIcons({root,attrs:{'stroke-width':2}})}
document.addEventListener('DOMContentLoaded',()=>refreshIcons());
window.addEventListener('resize',()=>updateBottomNavAlignment());
window.addEventListener('orientationchange',()=>setTimeout(updateBottomNavAlignment,180));
document.addEventListener('DOMContentLoaded',()=>{const cachedLogo=localStorage.getItem('sm_logo_url');if(cachedLogo)applyAppLogo(cachedLogo);});
const $=id=>document.getElementById(id);
const api=async(action,payload={})=>{
  const res=await fetch('/api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload:{...payload,token:state.token}})});
  const json=await res.json();if(!json.ok)throw new Error(json.error||'Terjadi kesalahan');return json.data;
};
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function money(n){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n||0))}
function todayISO(){const d=new Date();const y=d.getFullYear();const m=String(d.getMonth()+1).padStart(2,'0');const day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function qrDisplayUrl(url){const s=String(url||'');const m=s.match(/[?&]id=([a-zA-Z0-9_-]+)/)||s.match(/\/d\/([a-zA-Z0-9_-]+)/);return m?'https://drive.google.com/thumbnail?id='+m[1]+'&sz=w1000':s}
function applyAppLogo(url){if(url)localStorage.setItem('sm_logo_url',url);const src=url?qrDisplayUrl(url):'';[['loginBrandMark','brand-mark'],['sidebarBrandMark','brand-mark small']].forEach(([id,cls])=>{const el=$(id);if(!el)return;el.className=cls;el.innerHTML=src?`<img src="${escapeHtml(src)}" alt="Logo Sudi Mampir">`:'SM'})}
// Login bootstrap dikembalikan seperti versi sebelumnya; tidak memanggil API logo saat halaman dibuka.
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function updateBottomNavAlignment(){
 const nav=document.getElementById('bottomNav'),track=nav?.querySelector('.bottom-nav-track');if(!nav||!track)return;
 requestAnimationFrame(()=>{
  const visible=Array.from(track.children).filter(el=>getComputedStyle(el).display!=='none'&&!el.classList.contains('hidden'));
  const gap=parseFloat(getComputedStyle(track).columnGap)||3;
  const widths=visible.reduce((sum,el)=>sum+el.getBoundingClientRect().width,0);
  const style=getComputedStyle(nav);
  const available=Math.max(0,nav.clientWidth-(parseFloat(style.paddingLeft)||0)-(parseFloat(style.paddingRight)||0)-12);
  const fits=widths+Math.max(0,visible.length-1)*gap<=available;
  track.classList.toggle('is-centered',fits);
  nav.classList.toggle('nav-can-center',fits);
 });
}
async function syncLoginLogo(){
 try{const data=await api('logo.get');if(data?.logo_url)applyAppLogo(data.logo_url);}catch(e){/* Logo tersimpan lokal tetap digunakan; kegagalan logo tidak mengganggu login. */}
}
function showApp(){ $('loginView').classList.add('hidden');$('appView').classList.remove('hidden');$('userName').textContent=state.user.nama;$('userRole').textContent=state.user.role;$('avatar').textContent=(state.user.nama||'U').slice(0,1).toUpperCase();document.querySelectorAll('[data-owner]').forEach(x=>x.classList.toggle('hidden',state.user.role!=='OWNER'));document.querySelectorAll('[data-purchase-access]').forEach(x=>x.classList.toggle('hidden',state.user.role==='KASIR'));updateBottomNavAlignment();renderMobileHome();syncLoginLogo()}
function showLogin(){ $('appView').classList.add('hidden');$('loginView').classList.remove('hidden')}
const passwordToggle=$('togglePassword');
passwordToggle?.addEventListener('click',()=>{
 const input=$('password');
 const show=input.type==='password';
 input.type=show?'text':'password';
 passwordToggle.setAttribute('aria-pressed',String(show));
 passwordToggle.setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password');
 passwordToggle.title=show?'Sembunyikan password':'Tampilkan password';
 passwordToggle.innerHTML=show
  ?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18M10.6 10.7a2 2 0 002.7 2.7"/><path d="M9.9 5.2A10.8 10.8 0 0112 5c6.4 0 10 7 10 7a15.8 15.8 0 01-3.2 3.9M6.2 6.3C3.5 8.1 2 12 2 12s3.6 7 10 7c1.1 0 2.1-.2 3-.5"/></svg>'
  :'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>';
});
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginError').textContent='Memeriksa akun...';try{const d=await api('login',{username:$('username').value,password:$('password').value});state.token=d.token;state.user=d.user;localStorage.setItem('sm_token',state.token);$('password').value='';$('loginError').textContent='';showApp()}catch(err){$('loginError').textContent=err.message}});
async function performLogout(){try{await api('logout')}catch(e){}localStorage.removeItem('sm_token');state.token='';state.user=null;showLogin()}
$('logoutBtn').addEventListener('click',performLogout);
$('mobileLogoutTop')?.addEventListener('click',performLogout);
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));
function goHome(){renderMobileHome();window.scrollTo({top:0,behavior:'smooth'})}
$('homeBtn')?.addEventListener('click',goHome);
document.querySelectorAll('[data-home]').forEach(b=>b.addEventListener('click',goHome));
async function navigate(page){
 const navVersion=++state.navVersion;
 state.page=page;
 $('appView')?.classList.remove('mobile-home-mode');
 document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 const activeNav=document.querySelector(`#bottomNav [data-page="${page}"]:not(.hidden)`);
 if(activeNav&&window.matchMedia('(max-width: 800px)').matches)activeNav.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
 const names={dashboard:'Statistik',branches:'Manajemen Cabang',users:'Manajemen Pengguna',products:'Master Produk',purchases:'Input Belanja',purchaseList:'Daftar Belanja',salesList:'Daftar Penjualan',ingredients:'Master Bahan Baku',menu:'Daftar Menu',paymentSettings:'Pengaturan Pembayaran & Printer',whatsappGateway:'WhatsApp Gateway'};
 if($('pageTitle'))$('pageTitle').textContent=names[page]||page;
 if($('pageLabel'))$('pageLabel').textContent=(names[page]||page).toUpperCase();
 const content=$('content');if(content)content.innerHTML='<div class="panel empty">Memuat data...</div>';
 try{
  if(page==='dashboard')await renderDashboard();
  else if(page==='branches')await renderBranches();
  else if(page==='users')await renderUsers();
  else if(page==='products')await renderProducts();
  else if(page==='menu')await renderMenu();
  else if(page==='purchases')await renderPurchaseForm();
  else if(page==='purchaseList')await renderPurchaseList();
  else if(page==='salesList')await renderSalesList();
  else if(page==='ingredients')await renderIngredients();
  else if(page==='paymentSettings')await renderPaymentSettings();
  else if(page==='whatsappGateway')await renderWhatsAppGateway();
 }catch(e){
  if(navVersion===state.navVersion&&state.page===page&&e?.code!=='STALE_NAVIGATION'){
   const target=$('content');if(target)target.innerHTML=`<div class="panel empty"><b>Halaman belum dapat dimuat.</b><br>${escapeHtml(e.message||'Terjadi kesalahan.') }<br><button class="btn-light" type="button" onclick="navigate('${page}')">Coba lagi</button></div>`;
  }
 }finally{if(navVersion===state.navVersion)refreshIcons(document)}
}
async function renderMobileHome(){
 const app=$('appView');app.classList.add('mobile-home-mode');state.page='mobileHome';
 const menuButtons=[...document.querySelectorAll('#sideNav [data-page]')].filter(b=>!b.classList.contains('hidden')&&b.dataset.page);
 const menuItems=menuButtons.map(b=>({page:b.dataset.page,label:b.querySelector('span')?.textContent?.trim()||b.textContent.trim(),icon:b.querySelector('[data-lucide]')?.getAttribute('data-lucide')||'circle'}));
 $('content').innerHTML=`<section class="mobile-profile-card"><div class="mobile-profile-logo" id="mobileProfileLogo">SM</div><div class="mobile-profile-copy"><span>PROFIL APLIKASI</span><h2>Sudi Mampir</h2><p>Sistem Kasir & Manajemen Usaha</p><small>Selamat datang, ${escapeHtml(state.user?.nama||'Pengguna')}</small></div></section>
 <section class="mobile-home-stats" id="mobileHomeStats"><div class="mobile-mini-stat"><span><i data-lucide="shopping-cart"></i></span><small>Total Penjualan<br>(Hari Ini)</small><b>Memuat…</b></div><div class="mobile-mini-stat"><span><i data-lucide="shopping-bag"></i></span><small>Total Belanja<br>(Hari Ini)</small><b>Memuat…</b></div><div class="mobile-mini-stat"><span><i data-lucide="wallet"></i></span><small>Pendapatan Bersih<br>(Hari Ini)</small><b>Memuat…</b></div></section>
 <section class="mobile-launcher"><div class="mobile-launcher-heading"><div><span>AKSES CEPAT</span><h3>Menu Aplikasi</h3></div><small>${menuItems.length} menu tersedia</small></div><div class="mobile-launcher-grid">${menuItems.map(m=>`<button class="mobile-launcher-item" data-launch-page="${escapeHtml(m.page)}"><span class="launcher-icon"><i data-lucide="${escapeHtml(m.icon)}"></i></span><b>${escapeHtml(m.label)}</b></button>`).join('')}<button class="mobile-launcher-item mobile-launcher-logout" data-home-logout><span class="launcher-icon"><i data-lucide="log-out"></i></span><b>Keluar</b></button></div></section>`;
 const savedLogo=localStorage.getItem('sm_logo_url');if(savedLogo){$('mobileProfileLogo').innerHTML=`<img src="${escapeHtml(qrDisplayUrl(savedLogo))}" alt="Logo Sudi Mampir">`}
 document.querySelectorAll('[data-launch-page]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.launchPage)));
 document.querySelector('[data-home-logout]')?.addEventListener('click',performLogout);
 refreshIcons(document);
 try{const d=await api('dashboard');if(state.page!=='mobileHome')return;const values=[d.sales_today,d.purchases_today,d.net_today];document.querySelectorAll('#mobileHomeStats .mobile-mini-stat b').forEach((el,i)=>el.textContent=money(values[i]));}
 catch(e){document.querySelectorAll('#mobileHomeStats .mobile-mini-stat b').forEach(el=>el.textContent='—');toast('Ringkasan belum dapat dimuat: '+e.message)}
}


async function renderWhatsAppGateway(){
 const cfg=await api('whatsapp.settings.get');if(state.page!=='whatsappGateway')return;
 $('content').innerHTML=`<div class="wa-hero"><div><h2>WhatsApp Gateway</h2><p>Notifikasi otomatis penjualan dan pembelanjaan ke WhatsApp Owner</p></div><span class="wa-status">${cfg.tokenSaved?'TOKEN API TERSIMPAN':'TOKEN BELUM DIATUR'}</span></div>
 <div class="wa-tabs"><button class="active" data-wa-tab="connect">1. Hubungkan Perangkat</button><button data-wa-tab="template">2. Template Pesan & Uji Coba</button><button data-wa-tab="history">3. Riwayat Pengiriman</button></div><div id="waTabContent"></div>`;
 const pane=$('waTabContent');
 async function tab(name){document.querySelectorAll('[data-wa-tab]').forEach(b=>b.classList.toggle('active',b.dataset.waTab===name));
 if(name==='connect')pane.innerHTML=`<div class="panel wa-panel"><div class="panel-head"><h3>Konfigurasi Fonnte</h3><span class="badge">${cfg.tokenSaved?'Token tersimpan':'Belum terhubung'}</span></div><form id="waSettingsForm" class="form-grid"><label>Token API Fonnte<input name="token" type="password" autocomplete="new-password" placeholder="${cfg.tokenSaved?'Token sudah tersimpan — isi hanya jika ingin mengganti':''}"></label><label>Nomor WhatsApp Owner<input name="ownerNumber" required value="${escapeHtml(cfg.ownerNumber)}" placeholder="62812xxxxxxxx"></label><label class="wa-check"><input name="salesEnabled" type="checkbox" ${cfg.salesEnabled?'checked':''}> Kirim notifikasi penjualan otomatis</label><label class="wa-check"><input name="purchaseEnabled" type="checkbox" ${cfg.purchaseEnabled?'checked':''}> Kirim notifikasi pembelanjaan otomatis</label><div class="form-actions"><button class="btn primary">Simpan Pengaturan</button></div></form><p class="muted">Token disimpan di Script Properties Google Apps Script, tidak ditampilkan kembali di browser.</p><div class="form-actions"><button class="btn-light" id="waCheckToken">Periksa Token Fonnte</button><button class="btn-light" id="waTestConnection">Kirim Pesan Uji Coba</button></div><div id="waTokenCheckResult" class="muted" aria-live="polite"></div></div>`;
 $('waSettingsForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('whatsapp.settings.save',{fonnteToken:f.get('token'),ownerNumber:f.get('ownerNumber'),salesEnabled:String(f.has('salesEnabled')),purchaseEnabled:String(f.has('purchaseEnabled'))});toast('Pengaturan WhatsApp tersimpan');renderWhatsAppGateway()}catch(err){toast(err.message)}});
 $('waCheckToken')?.addEventListener('click',async()=>{const out=$('waTokenCheckResult');if(out)out.textContent='Memeriksa token ke Fonnte...';try{const r=await api('whatsapp.token.check');if(out)out.textContent=`Token valid • Perangkat: ${r.name||'-'} • Nomor: ${r.device||'-'} • Status: ${r.device_status||'-'} • Paket: ${r.package||'-'} • Kuota: ${r.quota||'-'} • Token GAS: ****${r.tokenLast4||'----'} (${r.tokenLength||0} karakter) • GAS: ...${r.scriptIdSuffix||'------'}`;toast('Token Fonnte valid')}catch(e){if(out)out.textContent=e.message;toast(e.message)}});
 $('waTestConnection')?.addEventListener('click',async()=>{const out=$('waTokenCheckResult');if(out)out.textContent='Memeriksa token GAS ke Fonnte, lalu mengirim pesan uji coba...';try{const r=await api('whatsapp.test');if(out)out.textContent=`Pesan uji coba berhasil dikirim • Perangkat: ${r.device||'-'} • Token GAS: ****${r.tokenLast4||'----'} (${r.tokenLength||0} karakter) • GAS: ...${r.scriptIdSuffix||'------'}`;toast('Pesan uji coba berhasil dikirim')}catch(e){if(out)out.textContent=e.message;toast(e.message)}});
 if(name==='template'){
 const tc=cfg.templateConfig||{}; const salesFields=tc.salesFields||{name:true,qty:true,unit:true,price:true,subtotal:true}; const purchaseFields=tc.purchaseFields||{name:true,qty:true,unit:true,price:true,subtotal:true};
 const infoFields=tc.infoFields||{branchName:true,actor:true,dateTime:true,transactionId:true,transactionTotal:true,dailySummary:true};
 const fieldChoices=(prefix,obj)=>[['name','Nama produk/barang'],['qty','Jumlah (Qty)'],['unit','Satuan'],['price','Harga satuan'],['subtotal','Subtotal']].map(([k,label])=>`<label class="wa-check"><input type="checkbox" name="${prefix}_${k}" ${obj[k]!==false?'checked':''}> ${label}</label>`).join('');
 const infoChoices=[['branchName','Nama cabang'],['actor','Petugas'],['dateTime','Tanggal/waktu'],['transactionId','Nomor transaksi'],['transactionTotal','Total transaksi'],['dailySummary','Ringkasan keuangan harian (total penjualan, total belanja, pendapatan bersih)']].map(([k,label])=>`<label class="wa-check"><input type="checkbox" name="i_${k}" ${infoFields[k]!==false?'checked':''}> ${label}</label>`).join('');
 pane.innerHTML=`<div class="panel"><h3>Template Pesan & Pengaturan Rincian</h3><p class="muted">Pilih informasi yang ingin ditampilkan. Pengaturan berlaku untuk notifikasi seluruh cabang.</p><form id="waTemplateForm"><div class="wa-template-grid"><article><h4>💰 Notifikasi Penjualan</h4><label>Kalimat pembuka<textarea name="salesIntro" rows="2">${escapeHtml(tc.salesIntro||'💰 NOTIFIKASI PENJUALAN SUDI MAMPIR')}</textarea></label><b>Informasi rincian</b>${fieldChoices('s',salesFields)}<label>Kalimat penutup<textarea name="salesOutro" rows="2">${escapeHtml(tc.salesOutro||'Notifikasi otomatis Sudi Mampir.')}</textarea></label></article><article><h4>🛒 Notifikasi Pembelanjaan</h4><label>Kalimat pembuka<textarea name="purchaseIntro" rows="2">${escapeHtml(tc.purchaseIntro||'🛒 NOTIFIKASI PEMBELANJAAN SUDI MAMPIR')}</textarea></label><b>Informasi rincian</b>${fieldChoices('p',purchaseFields)}<label>Kalimat penutup<textarea name="purchaseOutro" rows="2">${escapeHtml(tc.purchaseOutro||'Notifikasi otomatis Sudi Mampir.')}</textarea></label></article></div><div class="panel"><h4>Informasi transaksi yang ditampilkan</h4><p class="muted">Centang informasi yang ingin disertakan pada pesan WhatsApp. Pengaturan ini berlaku untuk notifikasi penjualan dan pembelanjaan.</p><div class="wa-template-grid">${infoChoices}</div></div><div class="form-actions"><button class="btn primary">Simpan Pengaturan Template</button><button type="button" class="btn-light" id="waTestTemplate">Kirim Pesan Uji Coba ke Owner</button></div></form></div>`;
 $('waTemplateForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),v={salesIntro:f.get('salesIntro'),salesOutro:f.get('salesOutro'),purchaseIntro:f.get('purchaseIntro'),purchaseOutro:f.get('purchaseOutro'),salesFields:{},purchaseFields:{},infoFields:{}};['name','qty','unit','price','subtotal'].forEach(k=>{v.salesFields[k]=f.has('s_'+k);v.purchaseFields[k]=f.has('p_'+k)});['branchName','actor','dateTime','transactionId','transactionTotal','dailySummary'].forEach(k=>v.infoFields[k]=f.has('i_'+k));try{await api('whatsapp.template.save',{templateConfig:v});toast('Pengaturan template berhasil disimpan');renderWhatsAppGateway();setTimeout(()=>document.querySelector('[data-wa-tab="template"]')?.click(),50)}catch(err){toast(err.message)}});
 $('waTestTemplate')?.addEventListener('click',async()=>{try{const r=await api('whatsapp.test');toast(`Terkirim dari perangkat ${r.device||'SudiMampir'}`)}catch(e){toast(e.message)}});
 }
 if(name==='history'){pane.innerHTML='<div class="panel"><div class="panel-head"><h3>Riwayat Pengiriman WhatsApp</h3><button class="btn-light" id="waRefresh">Segarkan</button></div><div id="waHistoryRows">Memuat riwayat...</div></div>';const load=async()=>{try{const rows=await api('whatsapp.history');const historyBox=$('waHistoryRows');if(!historyBox||!pane.isConnected||state.page!=='whatsappGateway')return;historyBox.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Cabang</th><th>Jenis</th><th>ID Transaksi</th><th>Nomor Tujuan</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(String(r.created_at||'').replace('T',' ').slice(0,19))}</td><td>${escapeHtml(r.nama_cabang)}</td><td>${escapeHtml(r.jenis)}</td><td>${escapeHtml(r.transaction_id)}</td><td>${escapeHtml(r.nomor_tujuan)}</td><td><span class="badge ${r.status==='TERKIRIM'?'':'wa-failed'}">${escapeHtml(r.status)}</span></td><td>${r.status==='GAGAL'?`<button class="btn-light" data-wa-retry="${escapeHtml(r.log_id)}">Kirim Ulang</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'Belum ada riwayat pengiriman.';document.querySelectorAll('[data-wa-retry]').forEach(b=>b.onclick=async()=>{try{await api('whatsapp.retry',{log_id:b.dataset.waRetry});toast('Notifikasi berhasil dikirim ulang');load()}catch(e){toast(e.message)}})}catch(e){$('waHistoryRows').textContent=e.message}};await load();$('waRefresh').onclick=load;}
 }
 document.querySelectorAll('[data-wa-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.waTab));await tab('connect');
}

async function renderDashboard(){
 const d=await api('dashboard');if(state.page!=='dashboard')return;
 const days=d.chart||[];
 $('content').innerHTML=`<div class="stats finance-stats"><div class="stat"><span class="icon"><i data-lucide="shopping-cart"></i></span><span class="label">Total Penjualan (Hari Ini)</span><strong>${money(d.sales_today)}</strong></div><div class="stat"><span class="icon"><i data-lucide="shopping-bag"></i></span><span class="label">Total Belanja (Hari Ini)</span><strong>${money(d.purchases_today)}</strong></div><div class="stat"><span class="icon"><i data-lucide="wallet"></i></span><span class="label">Pendapatan Bersih (Hari Ini)</span><strong>${money(d.net_today)}</strong></div></div>
 <div class="panel chart-panel"><div class="panel-head"><h3><i data-lucide="chart-column" class="inline-icon"></i> Persentase Pendapatan Harian – ${days.length} Hari</h3><span class="badge">Bulan berjalan</span></div><div class="chart-wrap"><canvas id="incomeChart" aria-label="Grafik persentase pendapatan harian"></canvas></div><div class="chart-legend"><span>Persentase pendapatan bersih dibanding penjualan</span><b>${Number(d.today_percent||0).toFixed(1).replace('.',',')}% hari ini</b></div></div>
 <div class="panel"><div class="panel-head"><h3>Cabang yang dapat diakses</h3></div>${d.cabang.length?`<div class="table-wrap"><table><thead><tr><th>Nama Cabang</th><th>Status</th></tr></thead><tbody>${d.cabang.map(b=>`<tr><td>${escapeHtml(b.nama_cabang)}</td><td><span class="badge">Aktif</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada cabang.</div>'}</div>`;
 drawIncomeChart(days);
}
function drawIncomeChart(rows){
 const canvas=$('incomeChart');if(!canvas)return;const ctx=canvas.getContext('2d');
 const dpr=window.devicePixelRatio||1,w=canvas.clientWidth||900,h=300;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);
 const pad={l:42,r:18,t:18,b:34},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b;
 ctx.clearRect(0,0,w,h);ctx.font='11px DM Sans, sans-serif';ctx.textAlign='right';ctx.textBaseline='middle';
 for(let v=0;v<=100;v+=20){const y=pad.t+ch-(v/100)*ch;ctx.strokeStyle='#e5eee9';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#84968d';ctx.fillText(v+'%',pad.l-8,y)}
 if(!rows.length)return;const x=i=>pad.l+(rows.length===1?cw/2:i*cw/(rows.length-1));const y=v=>pad.t+ch-(Math.max(0,Math.min(100,v))/100)*ch;
 const pts=rows.map((r,i)=>({x:x(i),y:y(Number(r.percent||0)),v:Number(r.percent||0),day:r.day}));
 const area=ctx.createLinearGradient(0,pad.t,0,h-pad.b);area.addColorStop(0,'rgba(22,190,104,.24)');area.addColorStop(1,'rgba(22,190,104,.015)');ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineTo(pts.at(-1).x,pad.t+ch);ctx.lineTo(pts[0].x,pad.t+ch);ctx.closePath();ctx.fillStyle=area;ctx.fill();
 const grad=ctx.createLinearGradient(pad.l,0,w-pad.r,0);grad.addColorStop(0,'#16c56a');grad.addColorStop(.45,'#b7d92b');grad.addColorStop(.7,'#ff9c16');grad.addColorStop(1,'#ef3434');ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=grad;ctx.lineWidth=3;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke();
 pts.forEach((p,i)=>{if(i===0||i===pts.length-1||i%Math.ceil(pts.length/10)===0){ctx.beginPath();ctx.arc(p.x,p.y,3.5,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle=grad;ctx.lineWidth=2;ctx.stroke()}if(i===0||i===pts.length-1||i%5===0){ctx.fillStyle='#71877c';ctx.textAlign='center';ctx.textBaseline='top';ctx.fillText(String(p.day),p.x,h-pad.b+9)}});
 canvas.onmousemove=e=>{const rect=canvas.getBoundingClientRect(),mx=e.clientX-rect.left;let nearest=pts.reduce((a,b)=>Math.abs(b.x-mx)<Math.abs(a.x-mx)?b:a,pts[0]);canvas.title=`Tanggal ${nearest.day}: ${nearest.v.toFixed(1)}%`};
}
