function paginationControls(idPrefix,total,page,size,onChange){
 const pages=size==='all'?1:Math.max(1,Math.ceil(total/size));
 const current=size==='all'?1:Math.min(page,pages);
 return `<div class="pagination-bar" id="${idPrefix}Pagination"><label class="pagination-size">Tampilkan
 <select id="${idPrefix}PageSize"><option value="10" ${size===10?'selected':''}>10 Data</option><option value="all" ${size==='all'?'selected':''}>Semua Data</option></select></label>
 <span class="pagination-info">Menampilkan ${total?((current-1)*(size==='all'?total:size)+1):0}–${size==='all'?total:Math.min(current*size,total)} dari ${total} data</span>
 <div class="pagination-buttons"><button type="button" class="btn-light" id="${idPrefix}Prev" ${current<=1?'disabled':''}>‹</button><span>Halaman ${current} / ${pages}</span><button type="button" class="btn-light" id="${idPrefix}Next" ${current>=pages?'disabled':''}>›</button></div></div>`;
}
function bindPagination(idPrefix,total,getPage,setPage,getSize,setSize,rerender){
 const sizeEl=$(idPrefix+'PageSize'),prev=$(idPrefix+'Prev'),next=$(idPrefix+'Next');
 if(sizeEl)sizeEl.onchange=()=>{setSize(sizeEl.value==='all'?'all':10);setPage(1);rerender()};
 if(prev)prev.onclick=()=>{setPage(Math.max(1,getPage()-1));rerender()};
 if(next)next.onclick=()=>{const size=getSize();setPage(Math.min(size==='all'?1:Math.ceil(total/size),getPage()+1));rerender()};
}

